export const CH5_PROGRESS_KEY = 'tenali-chapter5-progress';

export function ch5_loadProgress() {
  try {
    return JSON.parse(localStorage.getItem(CH5_PROGRESS_KEY) || '{}') || {};
  } catch {
    return {};
  }
}

export function ch5_saveProgress(p) {
  try {
    localStorage.setItem(CH5_PROGRESS_KEY, JSON.stringify(p));
  } catch {}
}

// --- Custom math renderer for Chapter5 ----------------------------------
// Beautiful stacked fractions, vertically centred (the global MathFrac uses
// a baseline-offset that makes fractions sit too low for our taste here).
// Also supports \times, \div, \approx, \le, \ge, \to, \$, etc.

export // Pre-substitute LaTeX-like operator macros into Unicode glyphs so they
// render properly when we hand off to the parser.
function ch5_subOps(s) {
  return String(s).replace(/\\times/g, '×').replace(/\\div/g, '÷').replace(/\\approx/g, '≈').replace(/\\sim\b/g, '~').replace(/\\to\b/g, '→').replace(/\\le\b/g, '≤').replace(/\\ge\b/g, '≥').replace(/\\ne\b/g, '≠').replace(/\\neq\b/g, '≠').replace(/\\cdot/g, '·').replace(/\\cdots/g, '⋯').replace(/\\pm/g, '±').replace(/\\pi/g, 'π').replace(/\\theta/g, 'θ').replace(/\\Delta/g, 'Δ').replace(/\\alpha/g, 'α').replace(/\\beta/g, 'β').replace(/\\gamma/g, 'γ').replace(/\\delta/g, 'δ').replace(/\\mu\b/g, 'μ').replace(/\\sigma/g, 'σ').replace(/\\omega/g, 'ω').replace(/\\sum/g, '∑').replace(/\\prod/g, '∏').replace(/\\int/g, '∫').replace(/\\angle/g, '∠').replace(/\\triangle/g, '△').replace(/\\square/g, '□').replace(/\\infty/g, '∞').replace(/\\sqrt\{([^{}]+)\}/g, '√($1)').replace(/\\sqrt(\d+)/g, '√$1').replace(/\\ell\b/g, 'ℓ').replace(/\\circ/g, '°').replace(/\\sin\b/g, 'sin').replace(/\\cos\b/g, 'cos').replace(/\\tan\b/g, 'tan').replace(/\\log\b/g, 'log').replace(/\\ln\b/g, 'ln').replace(/\\left\(/g, '(').replace(/\\right\)/g, ')').replace(/\\left\[/g, '[').replace(/\\right\]/g, ']').replace(/\\u2208/g, '∈').replace(/\\u2209/g, '∉').replace(/\\u2205/g, '∅').replace(/\\u222a/g, '∪').replace(/\\u2229/g, '∩').replace(/\\u2286/g, '⊆').replace(/\\u2282/g, '⊂').replace(/\\u2113/g, 'ℓ').replace(/\\u00b0/g, '°').replace(/\\u2019/g, '’').replace(/\\u2032/g, '′').replace(/\\u2013/g, '–').replace(/\\u2660/g, '♠').replace(/\\u2663/g, '♣').replace(/\\u2665/g, '♥').replace(/\\u2666/g, '♦').replace(/\\dot\{(\d)\}/g, '$1̇').replace(/\\\$/g, '$').replace(/\\%/g, '%');
}
// Recursive parser: handles \frac{NUM}{DEN} (with nesting) and ^N/^-N.

export // Recursive parser: handles \frac{NUM}{DEN} (with nesting) and ^N/^-N.
function ch5RenderMath(text) {
  if (text == null) return null;
  const src = ch5_subOps(text);
  const out = [];
  let i = 0,
    buf = '';
  const flush = () => {
    if (buf) {
      out.push(buf);
      buf = '';
    }
  };
  while (i < src.length) {
    if (src.startsWith('\\frac{', i)) {
      flush();
      let j = i + 6,
        depth = 1;
      const ns = j;
      while (j < src.length) {
        if (src[j] === '{') depth++;else if (src[j] === '}') {
          depth--;
          if (depth === 0) break;
        }
        j++;
      }
      const numStr = src.slice(ns, j);
      j++;
      if (src[j] !== '{') {
        buf += src.slice(i, j);
        i = j;
        continue;
      }
      j++;
      depth = 1;
      const ds = j;
      while (j < src.length) {
        if (src[j] === '{') depth++;else if (src[j] === '}') {
          depth--;
          if (depth === 0) break;
        }
        j++;
      }
      const denStr = src.slice(ds, j);
      j++;
      out.push(<Ch5Frac key={`f${out.length}`} num={ch5RenderMath(numStr)} den={ch5RenderMath(denStr)} />);
      i = j;
    } else if (src[i] === '^') {
      const m = src.slice(i).match(/^\^(-?\d+)/);
      if (m) {
        flush();
        out.push(<sup key={`s${out.length}`} style={{
          fontSize: '0.72em',
          verticalAlign: 'super'
        }}>{m[1]}</sup>);
        i += m[0].length;
      } else {
        buf += src[i];
        i++;
      }
    } else {
      buf += src[i];
      i++;
    }
  }
  flush();
  return out;
}

