export const CH23_PROGRESS_KEY = 'tenali-chapter23-progress';

export function ch23_loadProgress() {
  try {
    return JSON.parse(localStorage.getItem(CH23_PROGRESS_KEY) || '{}') || {};
  } catch {
    return {};
  }
}

export function ch23_saveProgress(p) {
  try {
    localStorage.setItem(CH23_PROGRESS_KEY, JSON.stringify(p));
  } catch {}
}

// --- Custom math renderer for Chapter 23 ----------------------------------

export function ch23_subOps(s) {
  return String(s).replace(/\\times/g, '×').replace(/\\div/g, '÷').replace(/\\approx/g, '≈').replace(/\\sim\b/g, '~').replace(/\\to\b/g, '→').replace(/\\le\b/g, '≤').replace(/\\ge\b/g, '≥').replace(/\\ne\b/g, '≠').replace(/\\neq\b/g, '≠').replace(/\\cdot/g, '·').replace(/\\cdots/g, '⋯').replace(/\\pm/g, '±').replace(/\\pi/g, 'π').replace(/\\theta/g, 'θ').replace(/\\Delta/g, 'Δ').replace(/\\alpha/g, 'α').replace(/\\beta/g, 'β').replace(/\\gamma/g, 'γ').replace(/\\delta/g, 'δ').replace(/\\mu\b/g, 'μ').replace(/\\sigma/g, 'σ').replace(/\\omega/g, 'ω').replace(/\\sum/g, '∑').replace(/\\prod/g, '∏').replace(/\\int/g, '∫').replace(/\\angle/g, '∠').replace(/\\triangle/g, '△').replace(/\\square/g, '□').replace(/\\infty/g, '∞').replace(/\\sqrt\{([^{}]+)\}/g, '√($1)').replace(/\\sqrt(\d+)/g, '√$1').replace(/\\ell\b/g, 'ℓ').replace(/\\circ/g, '°').replace(/\\sin\b/g, 'sin').replace(/\\cos\b/g, 'cos').replace(/\\tan\b/g, 'tan').replace(/\\log\b/g, 'log').replace(/\\ln\b/g, 'ln').replace(/\\vec\{([A-Z]{1,2})\}/g, '$1⃗') // overhead arrow combiner
  .replace(/\\mathbf\{([^{}]+)\}/g, '$1').replace(/\\equiv/g, '≡').replace(/\\left\(/g, '(').replace(/\\right\)/g, ')').replace(/\\left\[/g, '[').replace(/\\right\]/g, ']').replace(/\\u2208/g, '∈').replace(/\\u2209/g, '∉').replace(/\\u2205/g, '∅').replace(/\\u222a/g, '∪').replace(/\\u2229/g, '∩').replace(/\\u2286/g, '⊆').replace(/\\u2282/g, '⊂').replace(/\\u2113/g, 'ℓ').replace(/\\u00b0/g, '°').replace(/\\u2019/g, '’').replace(/\\u2032/g, '′').replace(/\\u2013/g, '–').replace(/\\u2660/g, '♠').replace(/\\u2663/g, '♣').replace(/\\u2665/g, '♥').replace(/\\u2666/g, '♦').replace(/\\dot\{(\d)\}/g, '$1̇').replace(/\\\$/g, '$').replace(/\\%/g, '%');
}

export function ch23RenderMath(text) {
  if (text == null) return null;
  const src = ch23_subOps(text).replace(/\\left\(/g, '(').replace(/\\right\)/g, ')');
  const out = [];
  let i = 0,
    buf = '';
  const flush = () => {
    if (buf) {
      out.push(buf);
      buf = '';
    }
  };
  // Helper: parse two brace groups starting at position after a token like \frac or \binom
  const parseTwoGroups = start => {
    // start points at the '{' of the first group
    let j = start;
    if (src[j] !== '{') return null;
    let depth = 1;
    j++;
    const ns = j;
    while (j < src.length) {
      if (src[j] === '{') depth++;else if (src[j] === '}') {
        depth--;
        if (depth === 0) break;
      }
      j++;
    }
    if (j >= src.length) return null;
    const a = src.slice(ns, j);
    j++;
    if (src[j] !== '{') return null;
    j++;
    depth = 1;
    const ds = j;
    while (j < src.length) {
      if (src[j] === '{') depth++;else if (src[j] === '}') {
        depth--;
        if (depth === 0) break;
      }
      j++;
    }
    if (j >= src.length) return null;
    const b = src.slice(ds, j);
    j++;
    return {
      a,
      b,
      end: j
    };
  };
  while (i < src.length) {
    if (src.startsWith('\\frac{', i)) {
      flush();
      const r = parseTwoGroups(i + 5);
      if (!r) {
        buf += src[i];
        i++;
        continue;
      }
      out.push(<Ch23Frac key={`f${out.length}`} num={ch23RenderMath(r.a)} den={ch23RenderMath(r.b)} />);
      i = r.end;
    } else if (src.startsWith('\\binom{', i)) {
      flush();
      const r = parseTwoGroups(i + 6);
      if (!r) {
        buf += src[i];
        i++;
        continue;
      }
      out.push(<Ch23ColVec key={`v${out.length}`} x={ch23RenderMath(r.a)} y={ch23RenderMath(r.b)} />);
      i = r.end;
    } else if (src[i] === '^') {
      const m = src.slice(i).match(/^\^(-?\d+)/);
      if (m) {
        flush();
        out.push(<sup key={`s${out.length}`} style={{
          fontSize: '0.72em',
          verticalAlign: 'super'
        }}>{m[1]}</sup>);
        i += m[0].length;
      } else {
        buf += src[i];
        i++;
      }
    } else {
      buf += src[i];
      i++;
    }
  }
  flush();
  return out;
}

export const CH23_AUTO_ADVANCE_MS = 5000;

export /* =====================================================================
 *  Chapter24App — Cambridge IGCSE Chapter 24 (Probability using tree
 *  diagrams and Venn diagrams)
 *
 *  Mounted at /chapter24. Same UX as Chapter5App–Chapter23App: ordered
 *  chain of lessons, every one unlocked from the start, slider to jump
 *  questions, MCQ with 1-9 keys + fill-in fallbacks, 5s auto-advance,
 *  completed lessons go green (with readable text), wrong answers
 *  appended to END of playList. See Tenali/skills/igcse-chapter/SKILL.md
 *  for the full pattern.
 *
 *  Sections covered: 24.1 sample spaces & tree diagrams; 24.2 calculating
 *  probabilities along the branches (independent events) and combining
 *  multiple paths; without-replacement (dependent) draws; 24.3
 *  probabilities from Venn diagrams (set notation, 2-set & 3-set);
 *  24.4 conditional probability via the formula and via two-way tables.
 *  See uploads PDF p. 830-849 (book ch. 24).
 * ===================================================================== */

const CH24_OPTION_LABEL = ['1', '2', '3', '4', '5', '6', '7', '8', '9'];

export function ch24_seededShuffle(n, key) {
  let h = 2166136261;
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  const rand = () => {
    h = Math.imul(h ^ h >>> 15, 2246822507);
    h = Math.imul(h ^ h >>> 13, 3266489909);
    return ((h ^= h >>> 16) >>> 0) / 4294967295;
  };
  const arr = Array.from({
    length: n
  }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

export function ch24_gcd(a, b) {
  a = Math.abs(a);
  b = Math.abs(b);
  while (b) {
    [a, b] = [b, a % b];
  }
  return a || 1;
}

export function ch24_reduce(n, d) {
  if (d === 0) return null;
  if (d < 0) {
    n = -n;
    d = -d;
  }
  const g = ch24_gcd(n, d);
  return {
    n: n / g,
    d: d / g
  };
}

export function ch24_parseFrac(raw) {
  if (raw == null) return null;
  let s = String(raw).trim().replace(/\\frac\{(-?\d+)\}\{(-?\d+)\}/g, '$1/$2').replace(/\s+/g, ' ').replace(/–/g, '-');
  if (!s) return null;
  const mixed = s.match(/^(-?)(\d+)\s+(\d+)\s*\/\s*(\d+)$/);
  if (mixed) {
    const sign = mixed[1] === '-' ? -1 : 1;
    const w = +mixed[2],
      n = +mixed[3],
      d = +mixed[4];
    if (d === 0) return null;
    return ch24_reduce(sign * (w * d + n), d);
  }
  const frac = s.match(/^(-?\d+)\s*\/\s*(-?\d+)$/);
  if (frac) {
    const n = +frac[1],
      d = +frac[2];
    if (d === 0) return null;
    return ch24_reduce(n, d);
  }
  const num = Number(s);
  if (Number.isFinite(num)) {
    if (Number.isInteger(num)) return {
      n: num,
      d: 1
    };
    const sign = num < 0 ? -1 : 1;
    const decimals = (s.split('.')[1] || '').length;
    const denom = Math.pow(10, decimals);
    return ch24_reduce(sign * Math.round(Math.abs(num) * denom), denom);
  }
  return null;
}

export function ch24_fracEqual(a, b) {
  return a && b && a.n === b.n && a.d === b.d;
}

export function ch24_normalizeNumStr(s) {
  return String(s).trim().replace(/[$,\s%]/g, '').replace(/–/g, '-');
}

export function ch24_numEqual(user, expected, tol) {
  const u = parseFloat(ch24_normalizeNumStr(user));
  if (!Number.isFinite(u)) return false;
  const t = tol != null ? tol : Math.max(0.005, Math.abs(expected) * 0.005);
  return Math.abs(u - expected) <= t;
}

export function ch24_checkFill(q, raw) {
  if (!raw || !raw.trim()) return false;
  switch (q.kind) {
    case 'fill-num':
      return ch24_numEqual(raw, q.answer, q.tol);
    case 'fill-frac':
      {
        const u = ch24_parseFrac(raw);
        const e = ch24_parseFrac(q.answer);
        return ch24_fracEqual(u, e);
      }
    case 'fill-text':
      return raw.trim().toLowerCase() === String(q.answer).trim().toLowerCase();
    default:
      return false;
  }
}

