const CH1_OPTION_LABEL = ['1', '2', '3', '4', '5', '6', '7', '8', '9'];

export function ch1_seededShuffle(n, key) {
  let h = 2166136261;
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  const rand = () => {
    h = Math.imul(h ^ h >>> 15, 2246822507);
    h = Math.imul(h ^ h >>> 13, 3266489909);
    return ((h ^= h >>> 16) >>> 0) / 4294967295;
  };
  const arr = Array.from({
    length: n
  }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

export function ch1_gcd(a, b) {
  a = Math.abs(a);
  b = Math.abs(b);
  while (b) {
    [a, b] = [b, a % b];
  }
  return a || 1;
}

export function ch1_reduce(n, d) {
  if (d === 0) return null;
  if (d < 0) {
    n = -n;
    d = -d;
  }
  const g = ch1_gcd(n, d);
  return {
    n: n / g,
    d: d / g
  };
}

export function ch1_parseFrac(raw) {
  if (raw == null) return null;
  let s = String(raw).trim().replace(/\\frac\{(-?\d+)\}\{(-?\d+)\}/g, '$1/$2').replace(/\s+/g, ' ').replace(/–/g, '-');
  if (!s) return null;
  const mixed = s.match(/^(-?)(\d+)\s+(\d+)\s*\/\s*(\d+)$/);
  if (mixed) {
    const sign = mixed[1] === '-' ? -1 : 1;
    const w = +mixed[2],
      n = +mixed[3],
      d = +mixed[4];
    if (d === 0) return null;
    return ch1_reduce(sign * (w * d + n), d);
  }
  const frac = s.match(/^(-?\d+)\s*\/\s*(-?\d+)$/);
  if (frac) {
    const n = +frac[1],
      d = +frac[2];
    if (d === 0) return null;
    return ch1_reduce(n, d);
  }
  const num = Number(s);
  if (Number.isFinite(num)) {
    if (Number.isInteger(num)) return {
      n: num,
      d: 1
    };
    const sign = num < 0 ? -1 : 1;
    const decimals = (s.split('.')[1] || '').length;
    const denom = Math.pow(10, decimals);
    return ch1_reduce(sign * Math.round(Math.abs(num) * denom), denom);
  }
  return null;
}

export function ch1_fracEqual(a, b) {
  return a && b && a.n === b.n && a.d === b.d;
}

export function ch1_normalizeNumStr(s) {
  return String(s).trim().replace(/[$,\s%]/g, '').replace(/–/g, '-');
}

export function ch1_numEqual(user, expected, tol) {
  const u = parseFloat(ch1_normalizeNumStr(user));
  if (!Number.isFinite(u)) return false;
  const t = tol != null ? tol : Math.max(0.005, Math.abs(expected) * 0.005);
  return Math.abs(u - expected) <= t;
}

export function ch1_checkFill(q, raw) {
  if (!raw || !raw.trim()) return false;
  switch (q.kind) {
    case 'fill-num':
      return ch1_numEqual(raw, q.answer, q.tol);
    case 'fill-frac':
      {
        const u = ch1_parseFrac(raw);
        const e = ch1_parseFrac(q.answer);
        return ch1_fracEqual(u, e);
      }
    case 'fill-text':
      return raw.trim().toLowerCase() === String(q.answer).trim().toLowerCase();
    default:
      return false;
  }
}

