export const CH3_PROGRESS_KEY = 'tenali-chapter3-progress';

export function ch3_loadProgress() {
  try {
    return JSON.parse(localStorage.getItem(CH3_PROGRESS_KEY) || '{}') || {};
  } catch {
    return {};
  }
}

export function ch3_saveProgress(p) {
  try {
    localStorage.setItem(CH3_PROGRESS_KEY, JSON.stringify(p));
  } catch {}
}

export function ch3_subOps(s) {
  return String(s).replace(/\\times/g, '×').replace(/\\div/g, '÷').replace(/\\approx/g, '≈').replace(/\\sim\b/g, '~').replace(/\\to\b/g, '→').replace(/\\le\b/g, '≤').replace(/\\ge\b/g, '≥').replace(/\\ne\b/g, '≠').replace(/\\neq\b/g, '≠').replace(/\\cdot/g, '·').replace(/\\cdots/g, '⋯').replace(/\\pm/g, '±').replace(/\\pi/g, 'π').replace(/\\theta/g, 'θ').replace(/\\Delta/g, 'Δ').replace(/\\xi/g, 'ξ').replace(/\\cap/g, '∩').replace(/\\cup/g, '∪').replace(/\\subset/g, '⊂').replace(/\\subseteq/g, '⊆').replace(/\\in\b/g, '∈').replace(/\\notin/g, '∉').replace(/\\emptyset/g, '∅').replace(/\\alpha/g, 'α').replace(/\\beta/g, 'β').replace(/\\gamma/g, 'γ').replace(/\\delta/g, 'δ').replace(/\\mu\b/g, 'μ').replace(/\\sigma/g, 'σ').replace(/\\omega/g, 'ω').replace(/\\sum/g, '∑').replace(/\\prod/g, '∏').replace(/\\int/g, '∫').replace(/\\angle/g, '∠').replace(/\\triangle/g, '△').replace(/\\square/g, '□').replace(/\\infty/g, '∞').replace(/\\sqrt\{([^{}]+)\}/g, '√($1)').replace(/\\sqrt(\d+)/g, '√$1').replace(/\\ell\b/g, 'ℓ').replace(/\\circ/g, '°').replace(/\\sin\b/g, 'sin').replace(/\\cos\b/g, 'cos').replace(/\\tan\b/g, 'tan').replace(/\\log\b/g, 'log').replace(/\\ln\b/g, 'ln').replace(/\\equiv/g, '≡').replace(/\\left\(/g, '(').replace(/\\right\)/g, ')').replace(/\\left\[/g, '[').replace(/\\right\]/g, ']').replace(/\\\$/g, '$').replace(/\\%/g, '%');
}

export function ch3RenderMath(text) {
  if (text == null) return null;
  const src = ch3_subOps(text).replace(/\\left\(/g, '(').replace(/\\right\)/g, ')');
  const out = [];
  let i = 0,
    buf = '';
  const flush = () => {
    if (buf) {
      out.push(buf);
      buf = '';
    }
  };
  while (i < src.length) {
    if (src.startsWith('\\frac{', i)) {
      flush();
      let j = i + 6,
        depth = 1;
      const ns = j;
      while (j < src.length) {
        if (src[j] === '{') depth++;else if (src[j] === '}') {
          depth--;
          if (depth === 0) break;
        }
        j++;
      }
      const numStr = src.slice(ns, j);
      j++;
      if (src[j] !== '{') {
        buf += src.slice(i, j);
        i = j;
        continue;
      }
      j++;
      depth = 1;
      const ds = j;
      while (j < src.length) {
        if (src[j] === '{') depth++;else if (src[j] === '}') {
          depth--;
          if (depth === 0) break;
        }
        j++;
      }
      const denStr = src.slice(ds, j);
      j++;
      out.push(<Ch3Frac key={`f${out.length}`} num={ch3RenderMath(numStr)} den={ch3RenderMath(denStr)} />);
      i = j;
    } else if (src[i] === '^') {
      const m = src.slice(i).match(/^\^(-?\d+)/);
      if (m) {
        flush();
        out.push(<sup key={`s${out.length}`} style={{
          fontSize: '0.72em',
          verticalAlign: 'super'
        }}>{m[1]}</sup>);
        i += m[0].length;
      } else {
        buf += src[i];
        i++;
      }
    } else {
      buf += src[i];
      i++;
    }
  }
  flush();
  return out;
}

